/bin/zsh -lc "Rscript - <<'RS'
options(stringsAsFactors = FALSE)
maf_path <- '/Users/linqingxuan/mcp_server/maftools_mcp/src/maftools_mcp/tcga_data/BRCA.maf'
outdir <- 'outputs'
dir.create(outdir, showWarnings=FALSE, recursive=TRUE)
genes <- c('TP53','PIK3CA','GATA3','CDH1')
maf <- read.delim(maf_path, sep='\\t', header=TRUE, quote='', comment.char='', check.names=FALSE)
parse_pos <- function(x) {
  x <- as.character(x)
  # Prefer the amino-acid coordinate after p. and an optional three-letter ref AA, e.g. p.R175H, p.Glu545Lys, p.E545K, p.*394Qext*.
  m <- regexec('(?:p\\\\.)?(?:[A-Za-z*]{1,3})([0-9]+)', x, perl=TRUE)
  got <- regmatches(x, m)
  as.integer(vapply(got, function(y) if (length(y) >= 2) y[2] else NA_character_, character(1)))
}
clean_hgvsp <- function(x) {
  x <- as.character(x)
  x[is.na(x) | x == '' | x == '.'] <- NA_character_
  x
}
domains <- readRDS(system.file('extdata', 'protein_domains.RDs', package='maftools'))
# Normalize likely column names from maftools domain resource.
find_col <- function(df, opts) {
  n <- names(df); hit <- match(tolower(opts), tolower(n), nomatch=0); if (any(hit > 0)) n[hit[hit>0][1]] else NA_character_
}
d_gene <- find_col(domains, c('HGNC','Hugo_Symbol','gene','symbol'))
d_start <- find_col(domains, c('Start','start','pfam_start','domain_start'))
d_end <- find_col(domains, c('End','end','pfam_end','domain_end'))
d_name <- find_col(domains, c('Domain','domain','PFAM','pfam','description','Domain_Name'))
if (any(is.na(c(d_gene,d_start,d_end,d_name)))) {
  stop('Could not resolve protein domain columns: ', paste(names(domains), collapse=', '))
}
combined <- list()
report <- list()
for (gene in genes) {
  g <- maf[maf"'$Hugo_Symbol == gene, , drop=FALSE]
  g$AA_Position <- parse_pos(g$HGVSp_Short)
  g$HGVSp_Short_Clean <- clean_hgvsp(g$HGVSp_Short)
  plot_tbl <- g[, intersect(c('"'Hugo_Symbol','Chromosome','Start_Position','End_Position','Variant_Classification','Variant_Type','Reference_Allele','Tumor_Seq_Allele2','Tumor_Sample_Barcode','Tumor_Sample_Barcode_min','HGVSc','HGVSp_Short','Transcript_ID','Exon_Number','AA_Position'), names(g)), drop=FALSE]
  write.table(plot_tbl, file=file.path(outdir, paste0(gene, '_mutation_table_for_plotting.tsv')), sep='\\t', quote=FALSE, row.names=FALSE, na='')
  recurrent <- aggregate(list(mutated_samples=g"'$Tumor_Sample_Barcode, total_mutation_events=g$Tumor_Sample_Barcode), by=list(Hugo_Symbol=g$Hugo_Symbol, AA_Position=g$AA_Position), FUN=function(z) NA)
  valid <- g[!is.na(g$AA_Position), , drop=FALSE]
  if (nrow(valid) > 0) {
    recurrent <- do.call(rbind, lapply(split(valid, valid$AA_Position), function(d) {
      data.frame(Hugo_Symbol=gene, AA_Position=unique(d$AA_Position)[1], mutated_samples=length(unique(d$Tumor_Sample_Barcode)), total_mutation_events=nrow(d), stringsAsFactors=FALSE)
    }))
    recurrent <- recurrent[order(-recurrent$mutated_samples, -recurrent$total_mutation_events, recurrent$AA_Position), ]
  } else {
    recurrent <- data.frame(Hugo_Symbol=character(), AA_Position=integer(), mutated_samples=integer(), total_mutation_events=integer())
  }
  write.table(recurrent, file=file.path(outdir, paste0(gene, '"'_recurrent_amino_acid_position_table.tsv')), sep='\\t', quote=FALSE, row.names=FALSE, na='')
  hsum <- if (nrow(valid) > 0) {
    do.call(rbind, lapply(split(valid, valid"'$HGVSp_Short_Clean, drop=TRUE), function(d) {
      if (is.na(unique(d$HGVSp_Short_Clean)[1])) return(NULL)
      data.frame(Hugo_Symbol=gene, HGVSp_Short=unique(d$HGVSp_Short_Clean)[1], AA_Position=unique(d$AA_Position)[1], mutated_samples=length(unique(d$Tumor_Sample_Barcode)), total_mutation_events=nrow(d), stringsAsFactors=FALSE)
    }))
  } else NULL
  if (is.null(hsum)) hsum <- data.frame(Hugo_Symbol=character(), HGVSp_Short=character(), AA_Position=integer(), mutated_samples=integer(), total_mutation_events=integer())
  hsum <- hsum[order(-hsum$mutated_samples, -hsum$total_mutation_events, hsum$AA_Position, hsum$HGVSp_Short), ]
  write.table(hsum, file=file.path(outdir, paste0(gene, '"'_recurrent_HGVSp_Short_summary_table.tsv')), sep='\\t', quote=FALSE, row.names=FALSE, na='')
  if (nrow(recurrent) > 0) {
    top <- recurrent[1, , drop=FALSE]
    gd <- domains[toupper(domains[[d_gene]]) == toupper(gene), , drop=FALSE]
    hit <- gd[as.integer(gd[[d_start]]) <= top"'$AA_Position & as.integer(gd[[d_end]]) >= top$AA_Position, , drop=FALSE]
    top$inside_pfam_domain <- nrow(hit) > 0
    top$pfam_domain_name <- if (nrow(hit) > 0) paste(unique(hit[[d_name]]), collapse='"';') else ''
    top"'$pfam_domain_start <- if (nrow(hit) > 0) paste(unique(hit[[d_start]]), collapse='"';') else ''
    top"'$pfam_domain_end <- if (nrow(hit) > 0) paste(unique(hit[[d_end]]), collapse='"';') else ''
    top_h <- hsum[hsum"'$AA_Position == top$AA_Position, ]
    top_h <- top_h[order(-top_h$mutated_samples, -top_h$total_mutation_events, top_h$HGVSp_Short), ]
    top$top_recurrent_HGVSp_Short_changes <- paste(head(paste0(top_h$HGVSp_Short, '"' (samples=', top_h"'$mutated_samples, '"', events=', top_h"'$total_mutation_events, '"')'), 5), collapse='; ')
  } else {
    top <- data.frame(Hugo_Symbol=gene, AA_Position=NA_integer_, mutated_samples=0L, total_mutation_events=0L, inside_pfam_domain=FALSE, pfam_domain_name='', pfam_domain_start='', pfam_domain_end='', top_recurrent_HGVSp_Short_changes='', stringsAsFactors=FALSE)
  }
  write.table(top, file=file.path(outdir, paste0(gene, '_single_top_selected_label_table.tsv')), sep='\\t', quote=FALSE, row.names=FALSE, na='')
  combined[[gene]] <- top
}
combined_df <- do.call(rbind, combined)
write.table(combined_df, file=file.path(outdir, 'all_genes_single_top_label_positions.tsv'), sep='\\t', quote=FALSE, row.names=FALSE, na='')
cat(capture.output(print(combined_df)), sep='\\n')
RS"

